(()=>{if(!document.getElementById('M04-lab'))return;const zh=document.documentElement.lang.startsWith('zh'),el=k=>document.getElementById('M04-'+k),def=[true,false,true,true],times=[2,3,4,5];let events=[...def],s={};function render(){let S=1;const values=[],risks=[4,3,2,1];times.forEach((tm,i)=>{if(events[i])S*=1-1/risks[i];values.push(S);el('event'+i).checked=events[i];});s={events:[...events],risk:risks,survival:values,S_at4:values[2]};const sx=t=>490+65*t,sy=v=>360-280*v;let svg='<path d="M490 80V360H840" fill="none" stroke="#9aadb7"/>';for(let j=0;j<=4;j++){const v=j/4;svg+=`<path d="M490 ${sy(v)}H840" stroke="#e0e7eb"/><text x="475" y="${sy(v)+4}" text-anchor="end">${v}</text>`;}for(let j=0;j<=5;j++)svg+=`<text x="${sx(j)}" y="385" text-anchor="middle">${j}</text>`;let d=`M${sx(0)} ${sy(1)}`,prev=1;times.forEach((tm,i)=>{d+=`H${sx(tm)}V${sy(values[i])}`;let y=110+i*65;svg+=`<text x="25" y="${y+5}">${i+1}</text><path d="M65 ${y}H${65+65*tm}" stroke="#a7bac3" stroke-width="2"/>`;svg+=events[i]?`<circle cx="${65+65*tm}" cy="${y}" r="7" fill="#d48745"/>`:`<path d="M${65+65*tm} ${y-10}V${y+10}" stroke="#167d87" stroke-width="3"/>`;if(!events[i])svg+=`<path d="M${sx(tm)} ${sy(values[i])-7}V${sy(values[i])+7}" stroke="#d48745" stroke-width="2"/>`;prev=values[i];});d+='H840';svg+=`<path d="${d}" fill="none" stroke="#167d87" stroke-width="3"/><text x="65" y="50">${zh?'部件观察：圆点事件 / 竖线删失':'Observation: circle event / tick censoring'}</text><text x="490" y="50">${zh?'生存概率 S(t)':'Survival probability S(t)'}</text><text x="650" y="425" text-anchor="middle">${zh?'时间（小时）':'Time (hours)'}</text>`;el('plot').innerHTML=svg;el('table').innerHTML=times.map((t,i)=>`<tr><td>${t}</td><td>${risks[i]}</td><td>${events[i]?1:0}</td><td>${values[i].toFixed(3)}</td></tr>`).join('');el('result').textContent=(zh?'4小时的累计存活概率':'Cumulative survival at hour 4')+` = ${s.S_at4.toFixed(3)}; `+(zh?'事件':'events')+` ${events.filter(Boolean).length}/4.`;}
function set(q){if(Array.isArray(q.events)&&q.events.length===4)events=q.events.map(Boolean);render();return JSON.parse(JSON.stringify(s));}for(let i=0;i<4;i++)el('event'+i).addEventListener('change',()=>{events[i]=el('event'+i).checked;render();});el('reset').addEventListener('click',()=>{events=[...def];render();});window.CourseLab={set,state:()=>JSON.parse(JSON.stringify(s)),reset:()=>{events=[...def];render();return JSON.parse(JSON.stringify(s));}};render();})();
